# Limbo-8 microcode: checks the table in instructions.py and makes everything from it.
# 
#     python microcode/microcode.py           write the files below
#     python microcode/microcode.py --check   write nothing, exit code 1 if a file is not up to date
# 
#     microcode/mc0.bin .. mc2.bin   EEPROM images (28C256): control word bits 0-7, 8-15, 16-23
#     logisim/limbo.circ             contents of the ROMs rom_mc0 .. rom_mc2 in the circuit "microcode"
#     docs/instruction-set.md        the tables between the "generated by microcode.py" markers
# 
# Microcode address (docs/architecture.md, section 6): A0-A7 = opcode, A8-A11 = step, A12 = condition,
# A13 and A14 = 0. Free opcodes, unused steps and A13/A14 = 1 hold HLT.


import itertools
import re
import sys
from pathlib import Path

import instructions as table

ROOT = Path(__file__).resolve().parent.parent
CIRC = ROOT / "logisim" / "limbo.circ"
DOC = ROOT / "docs" / "instruction-set.md"

SOURCES = {
    "A": 1,
    "B": 2,
    "MEM": 3,
    "ADD": 4,
    "AND": 5,
    "OR": 6,
    "XOR": 7,
    "SHR": 8,
    "XL": 9,
    "XH": 10,
    "PCL": 11,
    "PCH": 12,
    "Flags": 13,
    "$00": 14
} # bits 0-3

DESTINATIONS = {
    "-": 0,
    "A": 1,
    "B": 2,
    "T": 3,
    "IR": 4,
    "MEM": 5,
    "ML": 6,
    "MH": 7,
    "XL": 8,
    "XH": 9,
    "SP": 10,
    "Flags": 11
} # bits 4-7

ADDRESS = {
    "PC": 0,
    "X": 1,
    "SP": 2,
    "MAR": 3
} # bits 8-9

CARRY = {
    "0": 0,
    "1": 1,
    "C": 2
} # bits 17-18
BITS = {
    "PC_INC": 10,
    "PC_LD": 11,
    "X_INC": 12,
    "SP_INC": 13,
    "SP_DEC": 14,
    "STEP_RST": 15,
    "ALU_INV": 16,
    "FL_ZN": 19,
    "FL_C": 20,
    "HLT": 21
}

CHANGES = {
    "PC": {"PC_INC", "PC_LD"},
    "PCL": {"PC_INC", "PC_LD"},
    "PCH": {"PC_INC", "PC_LD"},
    "X": {"X_INC"},
    "XL": {"X_INC"},
    "XH": {"X_INC"},
    "SP": {"SP_INC", "SP_DEC"},
    "Flags": {"FL_ZN", "FL_C"}
}

class MicrocodeError(Exception):
    pass

class Step:
    def __init__(self, text):
        note = re.search(r"\((.*)\)", text)

        self.note = note[1] if note else None
        self.tokens = re.sub(r"\(.*\)", "", text).split()
        self.ab = self.src = self.dst = self.cin = None
        self.bits = set()

        for tok in self.tokens:
            if tok.startswith("AB=") and tok[3:] in ADDRESS:
                self.ab = tok[3:]

            elif tok.startswith("CIN=") and tok[4:] in CARRY:
                self.cin = tok[4:]

            elif "->" in tok and tok.split("->")[0] in SOURCES and tok.split("->")[1] in DESTINATIONS:
                self.src, self.dst = tok.split("->")

            elif tok in BITS:
                self.bits.add(tok)

            else:
                raise MicrocodeError(f"unknown signal '{tok}' in [{text}]")

    def writes(self):
        return self.dst in ("MEM", "SP")

    def word(self, last):
        w = SOURCES.get(self.src, 0) | DESTINATIONS.get(self.dst, 0) << 4 | ADDRESS.get(self.ab, 0) << 8
        w |= CARRY.get(self.cin, 0) << 17

        for bit in self.bits | ({"STEP_RST"} if last else set()):
            w |= 1 << BITS[bit]

        return w

def check(step, where):
    if "MEM" in (step.src, step.dst) and step.ab is None:
        raise MicrocodeError(f"{where}: memory access without AB=")
    
    if step.writes():
        changing = step.bits & (CHANGES.get(step.ab, set()) | CHANGES.get(step.src, set()))

        if changing:
            raise MicrocodeError(f"{where}: {', '.join(sorted(changing))} in a write step")

def load():
    instrs = {}

    for entries in table.SECTIONS.values():
        for e in entries:
            if e["code"] in instrs:
                raise MicrocodeError(f"opcode ${e['code']:02X} used twice")
            
            flows = []

            for a12 in (0, 1):
                texts = e["skip"] if "taken_on" in e and a12 != e["taken_on"] else e["steps"]
                flows.append([Step(t) for t in texts])

                if len(texts) + 1 > 16:
                    raise MicrocodeError(f"{e['name']}: more than 16 steps")
                
                for n, s in enumerate(flows[-1], 1):
                    check(s, f"{e['name']}, T{n}")

            instrs[e["code"]] = dict(e, flows=flows)

    return instrs


def images(instrs):
    fetch, halt = Step(table.FETCH), [Step("HLT")]
    words = [halt[0].word(last=True)] * (1 << 15)

    for code in range(256):
        for a12 in (0, 1):
            steps = [fetch] + (instrs[code]["flows"][a12] if code in instrs else halt)

            for n, s in enumerate(steps):
                words[a12 << 12 | n << 8 | code] = s.word(last=n == len(steps) - 1)

    words = [w ^ 1 << BITS["STEP_RST"] for w in words]

    return [bytes(w >> 8 * k & 0xFF for w in words) for k in range(3)]

def rom_contents(data):
    values = list(data)

    while values and values[-1] == 0:
        values.pop()

    tokens = []

    for value, run in itertools.groupby(values):
        n = len(list(run))
        tokens += [f"{n}*{value:x}"] if n >= 4 else [f"{value:x}"] * n

    lines = [" ".join(tokens[i:i + 8]) for i in range(0, len(tokens), 8)] or ["0"]

    return "addr/data: 15 8\n" + "\n".join(lines) + "\n"


def update_circ(text, imgs):
    circuit = re.search(r'<circuit name="microcode">.*?</circuit>', text, re.S)

    def fill(rom):
        k = int(re.search(r'<a name="label" val="rom_mc(\d)"/>', rom[0])[1])

        return re.sub(r'<a name="contents">.*?</a>', f'<a name="contents">{rom_contents(imgs[k])}</a>', rom[0], flags=re.S)

    roms, count = re.subn(r'<comp [^>]*name="ROM">.*?</comp>', fill, circuit[0], flags=re.S)

    if count != 3:
        raise MicrocodeError(f"circuit microcode: found {count} ROMs instead of rom_mc0 .. rom_mc2")
    
    return text[:circuit.start()] + roms + text[circuit.end():]

def show_step(s, last=False):
    tokens = [t.replace("->-", "→– (destination 0)").replace("->", "→") for t in s.tokens]
    text = " · ".join(tokens + (["STEP_RST"] if last else []))

    return text + (" ✎" if s.writes() else "") + (f" ({s.note})" if s.note else "")

def show_flow(steps, sep="<br>"):
    return sep.join(f"T{n}: {show_step(s, n == len(steps))}" for n, s in enumerate(steps, 1))


def row(ins):
    flows, code = ins["flows"], ins["code"]
    nbytes = 1 + sum("PC_INC" in s.bits for s in flows[0])
    bits = set().union(*(s.bits for s in flows[0]))

    if any(s.dst == "Flags" for s in flows[0]):
        flags = "all"

    else:
        flags = " ".join((["Z N"] if "FL_ZN" in bits else []) + (["C"] if "FL_C" in bits else [])) or "–"
    
    if "taken_on" in ins:
        on = ins["taken_on"]
        cycles = f"{len(flows[on]) + 1} / {len(flows[1 - on]) + 1}"
        steps = (f"**A12 = {on} ({'ZCN'[code & 3]} = {on}), jumps:** T1–T{len(table.JMP)} as `JMP`" f"<br>**A12 = {1 - on}, does not jump:** {show_flow(flows[1 - on], ' · ')}")

    else:
        cycles = len(flows[0]) + 1
        steps = show_flow(flows[0]) + (f"<br>({ins['note']})" if ins["note"] else "")

    return (f"| `${code:02X}` | `{code >> 4:04b} {code & 15:04b}` | `{ins['name']}` | {nbytes} | {cycles} " f"| {flags} | {steps} |")


def opcode_map(instrs):
    lines = ["| |" + "".join(f" x{k:X} |" for k in range(16)), "|---|" + "---|" * 16]

    for hi in sorted({code >> 4 for code in instrs}):
        cells = [f"`{instrs[c]['name']}`" if c in instrs else "·" for c in range(hi << 4, (hi + 1) << 4)]
        lines.append(f"| **{hi:X}x** | " + " | ".join(cells) + " |")

    return "\n".join(lines) + f"\n\nRows that are not shown are free. There are {len(instrs)} instructions in total."


def alu_tables():
    modes = [(mode, [Step(t) for t in steps]) for mode, steps in table.ALU_MODES]
    mode_lines = ["| Mode | Bits 1–0 | Bytes | Cycles | Steps before the last step |", "|---|---|---|---|---|"]

    for m, (mode, steps) in enumerate(modes):
        nbytes = 1 + sum("PC_INC" in s.bits for s in steps)
        flow = "<br>".join(f"T{n}: {show_step(s)}" for n, s in enumerate(steps, 1))
        mode_lines.append(f"| `{mode}` | `{m:02b}` | {nbytes} | {len(steps) + 2} | {flow} |")

    op_lines = ["| Operation | Bits 4–2 | " + " | ".join(f"`{mode}` ({m:02b})" for m, (mode, _) in enumerate(modes)) + " | last step (+ STEP_RST) |", "|---|---|" + "---|" * len(modes) + "---|"]
    
    for o, (name, last) in enumerate(table.ALU_OPS):
        codes = [0x80 | o << 2 | m for m in range(len(modes))]
        cells = " | ".join(f"`${c:02X}`<br>`{c >> 4:04b} {c & 15:04b}`" for c in codes)
        op_lines.append(f"| **{name}** | `{o:03b}` | {cells} | {show_step(Step(last))} |")
        
    return "\n".join(mode_lines), "\n".join(op_lines)


def update_doc(text, instrs):
    head = ("| Hex | Binary | Instruction | Bytes | Cycles | Flags | Micro steps (after T0) |\n" "|---|---|---|---|---|---|---|")
    blocks = {name: "\n".join([head] + [row(instrs[e["code"]]) for e in entries]) for name, entries in table.SECTIONS.items() if name != "alu"}
    blocks["map"] = opcode_map(instrs)
    blocks["alu-modes"], blocks["alu-ops"] = alu_tables()

    for name, block in blocks.items():
        marker = rf"(<!-- generated by microcode\.py: {name} -->\n).*?(\n<!-- end generated: {name} -->)"
        text, found = re.subn(marker, lambda m: m[1] + "\n" + block + "\n" + m[2], text, flags=re.S)
        
        if found != 1:
            raise MicrocodeError(f"{DOC.name}: marker for '{name}' missing")
        
    return text

def read(path):
    raw = path.read_bytes().decode("utf-8")
    return raw.replace("\r\n", "\n"), "\r\n" if "\r\n" in raw else "\n"

def main():
    check_only = "--check" in sys.argv

    try:
        instrs = load()
        imgs = images(instrs)
        circ, circ_nl = read(CIRC)
        doc, doc_nl = read(DOC)
        outputs = {ROOT / "microcode" / f"mc{k}.bin": img for k, img in enumerate(imgs)}
        outputs[CIRC] = update_circ(circ, imgs).replace("\n", circ_nl).encode("utf-8")
        outputs[DOC] = update_doc(doc, instrs).replace("\n", doc_nl).encode("utf-8")

    except MicrocodeError as e:
        print(f"error: {e}\nnothing written")

        return 2

    print(f"{len(instrs)} instructions")
    stale = False

    for path, data in outputs.items():
        name = path.relative_to(ROOT).as_posix()

        if path.exists() and path.read_bytes() == data:
            print(f"{name}: up to date")

        elif check_only:
            print(f"{name}: NOT up to date")
            stale = True

        else:
            path.write_bytes(data)
            print(f"{name}: written")
            
    return 1 if stale else 0


if __name__ == "__main__":
    sys.exit(main())
